// Cost cap and politeness: only rows without a score yet, at most LEAD_MAX per run.
const max = Number($env.LEAD_MAX || 50);
const rows = $input.all().filter(i => i.json.url && !i.json.fit_score);
return rows.slice(0, max);

// Reduce HTML to what an analyst would read, then build the Claude request (JSON built here on purpose: n8n expressions choke on '}}').
const ICP = $env.LEAD_ICP || 'small professional-services firms (law, accounting, dental) that still handle intake by phone or email';
const SYSTEM = 'You are a sales researcher. Given the text of a company website and an ideal customer profile (ICP), write a 3-line factual summary, score fit 1-10 (10 = textbook ICP match), give up to 4 concrete reasons, and write ONE opener sentence that references something specific from their site. Never invent facts that are not on the page. If the page is not a company site, score 1 and say why in red_flags.';
const SCHEMA = { type: 'object', additionalProperties: false,
  required: ['company','summary','fit_score','fit_reasons','opener','red_flags'],
  properties: { company: { type: 'string' }, summary: { type: 'string' }, fit_score: { type: 'integer', minimum: 1, maximum: 10 },
    fit_reasons: { type: 'array', items: { type: 'string' }, maxItems: 4 }, opener: { type: 'string' }, red_flags: { type: 'array', items: { type: 'string' } } } };
const strip = (html) => {
  let h = String(html || '');
  h = h.replace(/<(script|style|noscript|svg|nav|footer|iframe)[\s\S]*?<\/\1>/gi, ' ');
  const title = (h.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [,''])[1].trim();
  const desc = (h.match(/<meta[^>]+(?:name="description"|property="og:description")[^>]+content="([^"]*)"/i) || [,''])[1].trim();
  const headings = [...h.matchAll(/<h[123][^>]*>([\s\S]*?)<\/h[123]>/gi)].map(m => m[1].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim()).slice(0, 20);
  const text = h.replace(/<[^>]+>/g, ' ').replace(/&[a-z#0-9]+;/gi, ' ').replace(/\s+/g, ' ').trim().slice(0, 6000);
  return { title, description: desc, headings, text };
};
const src = $('Unscored rows only').all();
return $input.all().map((item, i) => {
  const url = src[i].json.url;
  const rowNumber = src[i].json.row_number;
  if (item.json.error || typeof item.json.data !== 'string') {
    return { json: { url, rowNumber, skip: true, error: item.json.error?.message || 'fetch failed' } };
  }
  const page = { url, ...strip(item.json.data) };
  if (page.text.length < 100) return { json: { url, rowNumber, skip: true, error: 'page has almost no text' } };
  const request = { model: $env.LEAD_MODEL || 'claude-sonnet-5', max_tokens: 1024, system: SYSTEM,
    messages: [{ role: 'user', content: JSON.stringify({ icp: ICP, page }) }],
    output_config: { format: { type: 'json_schema', schema: SCHEMA } } };
  return { json: { url, rowNumber, skip: false, page, request } };
});

// Parse + validate the assessment, flatten for the sheet.
const src = $('HTML -> text + request').all().filter(i => !i.json.skip);
return $input.all().map((item, i) => {
  const { url, rowNumber } = src[i].json;
  try {
    const block = (item.json.content || []).find(b => b.type === 'text');
    if (!block) throw new Error('no text block (stop_reason=' + item.json.stop_reason + ')');
    const a = JSON.parse(block.text);
    if (!(a.fit_score >= 1 && a.fit_score <= 10)) throw new Error('fit_score out of range');
    if (!a.company || !a.opener) throw new Error('missing company/opener');
    return { json: { url, row_number: rowNumber, company: a.company, summary: a.summary, fit_score: a.fit_score,
      fit_reasons: (a.fit_reasons || []).join(' | '), opener: a.opener, red_flags: (a.red_flags || []).join(' | '),
      scored_at: new Date().toISOString(), error: '' } };
  } catch (e) {
    return { json: { url, row_number: rowNumber, error: e.message } };
  }
});
